// Programme 100 : modèles de thème supplémentaires (Theme Builder). Chaque modèle est une PAGE du Page Builder qui devient le modèle d'une famille de pages
// (article, liste du blog, catégorie, auteur, étiquette, recherche, 404, page du site, formation, produit, catalogue). Seuls les éléments dynamiques acceptés par le moteur sont utilisés ;
// aucune image n'est fournie (emplacements ou étiquettes {{…}} remplies à l'affichage) et tout texte entre crochets est à remplacer.
const { helpers: { H, T, B, I, section } } = require("../patterns");

const post = (type, props = {}) => ({ type, props });
const ql = (o = {}) => post("querylist", { title: "", source: "posts", mode: "archive", count: 9, layout: "cards", showImage: true, showDate: true, ...o });
const shop = (o = {}) => post("shopgrid", { source: "archive", count: 12, columns: "3", orderby: "newest", ...o });
// grille à largeurs réglées (ex. « 2fr 1fr ») : une seule colonne sur tablette et mobile
const g = (tmpl, kids, o = {}) => ({ type: "grid", children: kids, styles: { desktop: { gridTemplate: tmpl, gap: "32px", alignItems: "start", ...o }, tablet: { columns: 1 }, mobile: { columns: 1 } } });
// grille à n colonnes égales, cartes de même hauteur
const gc = (n, kids, o = {}) => ({ type: "grid", children: kids, styles: { desktop: { columns: n, gap: "24px", alignItems: "stretch", ...o }, tablet: { columns: Math.min(n, 2) }, mobile: { columns: 1 } } });
const grp = (kids, o = {}) => ({ type: "group", children: kids, styles: { desktop: { display: "flex", flexDirection: "row", flexWrap: "wrap", gap: "12px", alignItems: "center", ...o } } });
const bx = (kids, o = {}) => ({ type: "stack", children: kids, styles: { desktop: { gap: "16px", paddingTop: "24px", paddingRight: "24px", paddingBottom: "24px", paddingLeft: "24px", borderRadius: "12px", backgroundColor: "token:surface", ...o } } });
const col = (kids, o = {}) => ({ type: "stack", children: kids, styles: { desktop: { gap: "16px", ...o } } });
const sticky = (kids, o = {}) => col(kids, { position: "sticky", top: "24px", ...o });
const ph = (ratio = "16/9", o = {}) => ({ type: "container", name: "Emplacement de l'image", children: [], styles: { desktop: { aspectRatio: ratio, backgroundColor: "token:surface", borderRadius: "12px", minHeight: "160px", ...o } } });
const bc = (...labels) => post("breadcrumb", { items: [{ label: "Accueil", url: "/" }, ...labels.map((l, i) => (i < labels.length - 1 ? { label: l, url: "/blog" } : { label: l }))], separator: "chevron" });
const bcShop = (...labels) => post("breadcrumb", { items: [{ label: "Accueil", url: "/" }, { label: "Boutique", url: "/boutique" }, ...labels.map((l) => ({ label: l }))], separator: "chevron" });
const share = (o = {}) => post("sharebuttons", { networks: ["facebook", "x", "linkedin", "whatsapp"], size: "32", shape: "circle", label: "Partager", ...o });
const info = (o = {}) => post("archiveinfo", o);
const meta2 = (o = {}) => post("postmeta", o);
const band = (kids, o = {}) => section(kids, { backgroundColor: "token:primary", alignItems: "center", borderRadius: "16px", ...o });
const cta = (title, label, url = "/contact") => bx([H(title, "3", { textAlign: "center" }), grp([B(label, url)], { justifyContent: "center" })], { alignItems: "center" });
const cats = (o = {}) => ql({ source: "categories", mode: "recent", count: 12, layout: "compact", ...o });
const tags = (o = {}) => ql({ source: "tags", mode: "popular", count: 24, layout: "inline", ...o });
const tab = (...titles) => post("tabs", { items: titles.map((t) => ({ title: t, text: `<p>[Contenu de l'onglet « ${t} » : à compléter.]</p>` })) });
const fine = (t, o = {}) => T(`<p>${t}</p>`, { fontSize: "14px", color: "token:muted", ...o });
const ibx = (icon, title, text, o = {}) => post("iconbox", { icon, title, text, titleLevel: "4", position: "top", size: "32", ...o });
const trust = (n = 3) => gc(n, [["send", "[Livraison]", "[Délais et frais, à préciser.]"], ["shield", "[Paiement sécurisé]", "[Moyens de paiement acceptés.]"], ["undo", "[Retours]", "[Conditions de retour.]"], ["help", "[Service client]", "[Comment vous joindre.]"]].slice(0, n).map((x) => ibx(x[0], x[1], x[2])));

const ED = ["blog", "magazine", "actualites", "portail-editorial"];
const SH = ["boutique-en-ligne", "catalogue-produits", "mode", "beaute", "electronique", "maison-decoration"];
const FO = ["formation-en-ligne", "centre-formation", "lms", "ecole"];
const PRO = ["services-professionnels", "conseil", "corporate"];

// [clé, famille, catégorie, nom, description, secteurs, type de site, mots-clés, composition]
const S = [];
const add = (key, themeType, category, name, description, sectors, siteType, keywords, build) => S.push({ key, themeType, category, name, description, sectors, siteType, keywords, build });

/* ======================= ARTICLES (single_post) ======================= */
add("article-sommaire-lateral", "single_post", "Articles", "Article avec sommaire latéral collant", "Contenu à gauche ; à droite, sommaire, partage et boîte auteur qui restent visibles pendant la lecture.", ED, "blog", ["sommaire", "guide", "article long", "table des matières"],
  () => [section([post("readingprogress"), g("3fr 1fr", [col([bc("Blog", "{{post.title}}"), H("{{post.title}}", "1"), meta2(), post("postcontent"), post("postterms"), post("postnav"), post("postcomments")]), sticky([post("toc", { title: "Dans cet article", depth: "3" }), share(), post("authorbox")])])])]);
add("article-magazine-pleine-largeur", "single_post", "Articles", "Article magazine pleine largeur", "Ouverture centrée avec catégorie, grand titre et visuel panoramique, puis texte resserré et articles liés.", ED, "blog", ["magazine", "reportage", "grand format", "visuel"],
  () => [section([post("postterms", { show: "category" }), H("{{post.title}}", "1", { textAlign: "center", fontSize: "56px" }), meta2({ align: "center" }), ph("21/9")], { alignItems: "center" }),
    section([post("postcontent"), grp([share()], { justifyContent: "center" }), post("authorbox"), ql({ title: "À lire aussi", mode: "related", count: 3 })], { maxWidth: "760px" })]);
add("article-bandeau-auteur", "single_post", "Articles", "Article avec bandeau d'auteur", "Titre, puis bandeau de présentation de l'auteur avant le texte, pour les contenus signés.", ED, "blog", ["auteur", "signature", "expert", "tribune"],
  () => [section([H("{{post.title}}", "1"), bx([post("authorbox", { heading: "", showLink: true }), meta2({ showAuthor: false })], { borderLeftWidth: "4px", borderStyle: "solid", borderColor: "token:primary" }), post("postcontent"), post("postterms"), post("postnav")], { maxWidth: "820px" })]);
add("article-lecture-longue-etroite", "single_post", "Articles", "Lecture longue en colonne étroite", "Colonne de lecture étroite, interligne généreux et barre de progression, pour les textes à lire jusqu'au bout.", ED, "blog", ["lecture longue", "essai", "confort de lecture", "progression"],
  () => [section([post("readingprogress", { position: "top", thickness: 4 }), H("{{post.title}}", "1", { fontSize: "40px" }), meta2({ separator: "bar" }), { type: "divider" }, post("postcontent"), { type: "divider" }, post("postnav")], { maxWidth: "640px", paddingTop: "96px" })]);
add("article-articles-lies-grille", "single_post", "Articles", "Article et grille d'articles liés", "Article complet suivi d'une grille de trois articles liés pour prolonger la visite.", ED, "blog", ["articles liés", "recommandations", "suite de lecture"],
  () => [section([H("{{post.title}}", "1"), meta2(), post("postcontent"), post("postterms")], { maxWidth: "820px" }), section([H("[Pour aller plus loin]", "2"), ql({ mode: "related", count: 3, showMeta: true })])]);
add("article-sommaire-haut", "single_post", "Articles", "Article avec sommaire en tête", "Sommaire numéroté placé sous le titre, dans un encadré, avant le corps de l'article.", ED, "blog", ["tutoriel", "sommaire numéroté", "guide pratique"],
  () => [section([post("readingprogress", { position: "bottom" }), H("{{post.title}}", "1"), meta2({ showReading: true }), bx([post("toc", { title: "Au programme", depth: "2", numbered: true })]), post("postcontent"), post("postterms"), post("authorbox")], { maxWidth: "820px" })]);
add("article-sidebar-widgets", "single_post", "Articles", "Article avec barre latérale du site", "Deux tiers pour l'article, un tiers pour la barre latérale gérée dans Apparence → Widgets.", ED, "blog", ["barre latérale", "widgets", "blog classique"],
  () => [section([g("2fr 1fr", [col([H("{{post.title}}", "1"), meta2(), post("postcontent"), post("postterms"), post("postnav"), post("postcomments")]), post("sidebar", { label: "Barre latérale" })])])]);
add("article-partage-lateral", "single_post", "Articles", "Article avec partage dans la marge", "Boutons de partage collés dans la marge de gauche, texte principal à droite.", ED, "blog", ["partage", "réseaux sociaux", "viralité"],
  () => [section([g("1fr 6fr", [sticky([share({ label: "", size: "40" })]), col([H("{{post.title}}", "1"), meta2(), post("postcontent"), post("postterms"), post("authorbox"), post("postcomments")])], { gap: "24px" })])]);
add("article-titre-et-visuel", "single_post", "Articles", "Article titre et visuel côte à côte", "Titre, catégorie et date à gauche, visuel à droite, puis texte sur toute la largeur de lecture.", ED, "blog", ["à la une", "visuel", "en-tête", "deux colonnes"],
  () => [section([g("1fr 1fr", [col([post("postterms", { show: "category" }), H("{{post.title}}", "1", { fontSize: "44px" }), T("<p>{{post.excerpt}}</p>", { fontSize: "20px", color: "token:muted" }), meta2()], { justifyContent: "center" }), ph("4/3")], { alignItems: "center" })]),
    section([post("postcontent"), post("postnav")], { maxWidth: "760px", paddingTop: "0px" })]);
add("article-chapeau-et-citation", "single_post", "Articles", "Article avec chapeau mis en avant", "Résumé de l'article en grand chapeau, filet de séparation, puis le texte et l'encadré de la rédaction.", ED, "blog", ["chapeau", "résumé", "éditorial", "citation"],
  () => [section([H("{{post.title}}", "1"), T("<p>{{post.excerpt}}</p>", { fontSize: "24px", lineHeight: "1.5", color: "token:muted" }), { type: "divider" }, post("postcontent"), { type: "quote", props: { text: "[Phrase forte de l'article à mettre en exergue.]", author: "{{post.author}}" } }, post("postterms")], { maxWidth: "720px" })]);
add("article-tutoriel-pas-a-pas", "single_post", "Articles", "Tutoriel pas à pas", "Prérequis en liste, sommaire numéroté, texte et questions fréquentes en fin d'article.", ED.concat(FO), "blog", ["tutoriel", "pas à pas", "prérequis", "faq"],
  () => [section([{ type: "badge", props: { text: "[Tutoriel]", tone: "primary" } }, H("{{post.title}}", "1"), meta2({ showAuthor: false }), g("1fr 1fr", [bx([H("Avant de commencer", "3"), { type: "iconlist", props: { items: [{ text: "[Prérequis 1]", icon: "check" }, { text: "[Prérequis 2]", icon: "check" }, { text: "[Matériel ou outil]", icon: "check" }] } }]), bx([post("toc", { title: "Les étapes", numbered: true })])]), post("postcontent"), H("Questions fréquentes", "2"), { type: "accordion", props: { items: [{ q: "[Question fréquente ?]", a: "[Réponse courte.]" }, { q: "[Autre question ?]", a: "[Réponse courte.]" }] } }], { maxWidth: "860px" })]);
add("article-actualite-breve", "single_post", "Articles", "Actualité brève", "Format court : fil d'Ariane, titre, date, texte et lecture complémentaire en liste compacte.", ED.concat(["association", "ong"]), "blog", ["actualité", "communiqué", "brève", "news"],
  () => [section([bc("Actualités", "{{post.title}}"), H("{{post.title}}", "1", { fontSize: "36px" }), meta2({ showReading: false, showAuthor: false }), post("postcontent"), { type: "divider" }, ql({ title: "Dernières actualités", mode: "recent", count: 4, layout: "compact", showImage: false })], { maxWidth: "760px" })]);
add("article-interview", "single_post", "Articles", "Interview avec fiche de l'invité", "Fiche latérale (auteur, rubrique, durée de lecture) à gauche, titre et entretien à droite.", ED, "blog", ["interview", "entretien", "portrait", "invité"],
  () => [section([g("1fr 2fr", [sticky([bx([post("authorbox", { heading: "Propos recueillis par" }), post("postterms"), meta2({ showDate: false, showAuthor: false })])]), col([H("{{post.title}}", "1"), T("<p>{{post.excerpt}}</p>", { fontSize: "20px" }), post("postcontent"), post("postnav")])])])]);
add("article-etude-de-cas", "single_post", "Articles", "Étude de cas avec faits clés", "Trois repères (contexte, action, résultat) sous le titre, récit complet puis appel à contacter.", PRO.concat(["agence-digitale", "marketing"]), "vitrine", ["étude de cas", "réalisation", "résultats", "projet client"],
  () => [section([post("postterms", { show: "category", look: "text" }), H("{{post.title}}", "1"), gc(3, [ibx("search", "[Contexte]", "[Le besoin de départ.]"), ibx("zap", "[Action]", "[Ce qui a été mis en place.]"), ibx("trophy", "[Résultat]", "[Ce qui a changé, avec une source réelle.]")]), post("postcontent"), cta("[Un projet similaire ?]", "[Parlons-en]")], { maxWidth: "900px" })]);
add("article-trois-colonnes", "single_post", "Articles", "Article en trois colonnes", "Sommaire à gauche, texte au centre, articles populaires à droite : mise en page de portail éditorial.", ED, "blog", ["portail", "trois colonnes", "sommaire", "populaires"],
  () => [section([g("1fr 3fr 1fr", [sticky([post("toc", { title: "Sommaire", depth: "2" })]), col([H("{{post.title}}", "1"), meta2(), post("postcontent"), post("postterms")]), col([ql({ title: "Les plus lus", mode: "popular", count: 5, layout: "compact", showImage: false }), tags({ title: "Étiquettes" })])], { gap: "40px" })], { paddingLeft: "24px" })]);
add("article-discussion", "single_post", "Articles", "Article centré sur la discussion", "Texte puis zone de commentaires en avant, avec les articles les plus commentés à côté.", ED.concat(["communaute"]), "blog", ["commentaires", "débat", "communauté", "discussion"],
  () => [section([H("{{post.title}}", "1"), meta2({ showComments: true }), post("postcontent")], { maxWidth: "820px" }), section([g("2fr 1fr", [post("postcomments", { heading: "Votre avis" }), ql({ title: "Les plus commentés", mode: "commented", count: 4, layout: "compact", showImage: false })])])]);
add("article-alerte-en-tete", "single_post", "Articles", "Article avec message important", "Bandeau d'information en tête (mise à jour, avertissement), puis le titre, le texte et les étiquettes.", ED.concat(["juridique", "finance", "assurance"]), "blog", ["avertissement", "mise à jour", "information importante"],
  () => [section([{ type: "alert", props: { tone: "info", title: "[À savoir]", text: "[Information à connaître avant de lire : mise à jour, réserve, contexte.]" } }, H("{{post.title}}", "1"), meta2({ showUpdated: true }), post("postcontent"), post("postterms"), post("postnav")], { maxWidth: "800px" })]);
